import{n as e,t}from"./jsx-runtime-lw2jiZar.js";import{t as n}from"./boxes-Q12yMsyh.js";import{C as r,D as i,E as a,M as o,N as s,O as c,P as l,T as u,b as d,k as f,p}from"./shared-C5BCElVa.js";var m=e(`ClipboardCheck`,[[`rect`,{width:`8`,height:`4`,x:`8`,y:`2`,rx:`1`,ry:`1`,key:`tgr4d6`}],[`path`,{d:`M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2`,key:`116196`}],[`path`,{d:`m9 14 2 2 4-4`,key:`df797q`}]]),h=t();function g({module:e}){return(0,h.jsxs)(s,{children:[(0,h.jsx)(o,{variant:`project`,chip:e??`Блок 12 · Проверяемая передача`,title:`Проверка слоёв Planner`,intro:`HTTP уже проверен отдельно. Теперь посмотрим, что тесты говорят о модели, хранилище и сервисе, и найдём свойства, для которых тестов пока нет.`,tags:[{icon:(0,h.jsx)(n,{size:14}),label:`границы слоёв`},{icon:(0,h.jsx)(m,{size:14}),label:`карта доказательств`}]}),(0,h.jsxs)(l,{number:`00`,title:`От проверок API к внутренним гарантиям`,children:[(0,h.jsx)(c,{children:`В занятии 58.2 мы проверяли фильтры, сортировку, OpenAPI и ответы маршрутов. Это важно для клиента API, но не показывает, как Task и хранилища ведут себя внутри Planner.`}),(0,h.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`HTTP-контракт и выборка уже проверены через TestClient.`},{title:`Новый вопрос`,description:`Что уже проверяют тесты модели, хранилища и сервиса, а что пока лишь записано в матрице?`},{title:`Результат`,description:`Добавим только недостающие unit-тесты и исправим матрицу по фактическим тестам.`}]}),(0,h.jsx)(`p`,{children:`Сначала сверим матрицу с тестами API, CLI, файлового хранилища и сервиса. Затем закроем два пробела: проверим список tags у Task и копирование списка в MemoryStorage. Первый тест напрямую создаёт Task, второй напрямую вызывает хранилище. В следующем занятии эти отдельные проверки помогут собрать одну историю HTTP-запросов. Здесь новый workflow-тест и повторы CRUD-проверок не нужны.`})]}),(0,h.jsxs)(l,{number:`01`,title:`У каждого теста есть граница`,children:[(0,h.jsx)(c,{children:`Сначала решим, что именно должен доказать тест. Название файла и число проверок этого не показывают. Важно, какой объект мы вызываем и что проверяем после вызова.`}),(0,h.jsx)(`p`,{children:`Тест Task вызывает модель и проверяет её поля. Тест хранилища вызывает MemoryStorage или JsonStorage. Тест сервиса работает через PlannerService и переданное ему хранилище. CLI-тест проверяет команды, сообщения и вызовы приложения. HTTP-тест проходит через FastAPI и проверяет статус и ответ. Один сценарий может затронуть несколько слоёв, но вывод делаем только о том, что тест проверил.`}),(0,h.jsx)(p,{prompt:`Соединим уровень проверки с тем, что он может подтвердить.`,leftTitle:`Уровень`,rightTitle:`Наблюдаемое обещание`,pairs:[{left:`Task`,right:`Данные и изменяемые поля одного объекта`},{left:`MemoryStorage`,right:`Граница копии списка и ссылки на Task`},{left:`JsonStorage`,right:`Полная запись и восстановление из файла`},{left:`PlannerService`,right:`Правило действия, чтение и сохранение`},{left:`CLI или HTTP`,right:`Поведение интерфейса и его ответ`}],explanation:`Тест может пройти через несколько компонентов, но его результат подтверждает только проверенные входы, вызовы и наблюдения.`}),(0,h.jsx)(`p`,{children:`Например, ответ 422 через TestClient показывает, что HTTP отклонил запрос. Это не доказывает отдельно поведение модели или сервиса: сначала FastAPI разбирает запрос, затем маршрут обрабатывает его и формирует ответ. Успешный ответ API тоже может не содержать tags, потому что это внутреннее поле Task. Чтобы проверить tags, нужно посмотреть полную запись или прочитать её из хранилища.`}),(0,h.jsx)(`p`,{children:`Матрица помогает не гадать. Для каждого риска укажем слой, файл или тест и проверяемый результат. Строка «не покрыто» тоже полезна: она показывает, какого теста не хватает.`}),(0,h.jsx)(`p`,{children:`Например, в строке про tags укажем модель и тест, который создаёт две задачи и меняет только одну. В строке про MemoryStorage укажем прямой тест хранилища, который меняет список и объект Task. Так читатель матрицы увидит не только имя файла, но и причину, по которой этому тесту можно доверять.`})]}),(0,h.jsxs)(l,{number:`02`,title:`Список tags принадлежит экземпляру Task`,children:[(0,h.jsx)(c,{children:`Task хранит id, title, priority, is_done и tags. У каждой задачи должны быть свои значения. Особенно важно, чтобы изменяемый список tags не оказался общим для разных задач.`}),(0,h.jsx)(`p`,{children:`Для каждой новой Task модель создаёт отдельный список tags. Поэтому две задачи без переданного списка начинают с пустых, независимых списков. Добавим метку первой задаче и проверим, что список второй пуст. Для этого достаточно двух объектов Task: Planner и HTTP-клиент не нужны.`}),(0,h.jsx)(`p`,{children:`Представим две бумажные карточки задач, созданные по одному шаблону. На каждой своя строка меток: изменение одной карточки не меняет другую. Это пример только для tags. Копирует ли хранилище весь объект Task, проверим отдельно.`}),(0,h.jsx)(`p`,{children:`Проверка одной задачи не обнаружит общий список. Поэтому тест создаёт две задачи по умолчанию, добавляет метку одной и сравнивает оба списка. Так тест проверяет именно модель.`}),(0,h.jsx)(d,{question:`Две задачи созданы без аргумента tags. После добавления метки первой задаче, какой результат подтверждает независимость списков?`,options:[`У первой есть метка, у второй остаётся пустой список`,`Обе задачи получают одинаковую метку`,`Изменение возможно только после JsonStorage.save()`],correctIndex:0,explanation:`Поле tags изменяемое, поэтому каждая Task должна получить свою коллекцию. Здесь проверяется модель, а не запись в файл.`}),(0,h.jsx)(`p`,{children:`Это одна небольшая unit-проверка: она подтверждает, что списки двух задач независимы. Она не проверяет названия, другие поля или API. В матрице как раз не хватало такого теста.`})]}),(0,h.jsxs)(l,{number:`03`,title:`MemoryStorage копирует список, но не сами Task`,children:[(0,h.jsx)(c,{children:`MemoryStorage принимает и возвращает задачи списком. При создании, загрузке и сохранении он копирует сам список, но оставляет в нём те же объекты Task.`}),(0,h.jsx)(`p`,{children:`Если после создания storage добавить задачу в исходный список, его содержимое не изменится. Если очистить список из load(), внутренний список тоже останется прежним. Чтобы изменить набор, нужно вызвать save() с новым списком. Здесь мы проверяем списки, а не копирование задач.`}),(0,h.jsx)(`p`,{children:`При этом оба списка могут содержать одну Task. Если изменить её поле, новое значение будет видно и после следующего load(). Это поверхностная копия: список новый, объект общий.`}),(0,h.jsx)(`p`,{children:`Представим два подноса с карточками. Если убрать карточку с одного подноса, на другом она останется. Но сама карточка общая: отметка на ней видна на обоих подносах. Так проще запомнить разницу между копией списка и копией задач.`}),(0,h.jsx)(u,{question:`Какое наблюдение соответствует поверхностной копии списка в MemoryStorage?`,left:{title:`Отдельный список`,code:`loaded = storage.load()
loaded.clear()
assert storage.load() == [task]`,note:`Очистка возвращённого контейнера не удаляет элементы из внутреннего списка.`},right:{title:`Отдельная копия Task`,code:`loaded = storage.load()
loaded[0].mark_done()
assert storage.load()[0].is_done is False`,note:`Такой вывод потребовал бы копировать объект Task, чего MemoryStorage не обещает.`},preferred:`left`,explanation:`MemoryStorage копирует list(tasks), но не создаёт копии каждого объекта. Контейнеры независимы, Task остаётся общей ссылкой.`}),(0,h.jsx)(`p`,{children:`JsonStorage работает с файлом: записывает поля Task, включая tags, а при чтении создаёт Task из JSON. Существующие тесты уже проверяют восстановление, старый формат без tags и ошибку чтения без перезаписи файла. В тесте MemoryStorage повторять их не нужно.`}),(0,h.jsx)(`p`,{children:`Практическая проверка повторяет именно этот порядок: сначала создаём storage с исходным списком, затем проверяем результат load(), после этого передаём новый список в save(). В каждом шаге сравниваем содержимое, чтобы увидеть, меняет ли внешний список внутренний. Отдельно меняем поле Task: эта часть показывает, что объект остался общим.`})]}),(0,h.jsxs)(l,{number:`04`,title:`Сервисное чтение и запись требуют разных доказательств`,children:[(0,h.jsx)(c,{children:`PlannerService выполняет действие через переданное хранилище. Результат метода и факт сохранения нужно проверять отдельно.`}),(0,h.jsx)(`p`,{children:`При чтении сервис загружает данные, выбирает нужные и возвращает их. Если байты JSON не изменились, это ещё не доказывает, что save() не вызывался: файл могли записать с теми же данными. В тестах уже есть ObservedStorage со счётчиком save. После чтения проверим, что счётчик равен нулю.`}),(0,h.jsx)(`p`,{children:`Изменение проверяется иначе. Создадим новый PlannerService с тем же временным файлом и прочитаем данные заново. Сравним полную Task, включая id, поля и tags, а также проверим, что соседняя задача осталась. Это уже делают test_service_persistence.py после PATCH и PUT. Файл test_services.py проверяет чтение и счётчик save.`}),(0,h.jsx)(`p`,{children:`Эти готовые тесты отвечают на разные вопросы. Счётчик save показывает, вызывал ли сервис запись во время чтения. Новый сервис показывает, сохранились ли данные после изменения. Поэтому третья карточка просит найти оба доказательства в существующих файлах, а не повторить сценарии в новом тесте.`}),(0,h.jsx)(`p`,{children:`Ответ метода похож на чек: он показывает результат операции, но не то, что осталось в хранилище. Это покажет повторное чтение. А для проверки чтения счётчик save точнее, чем сравнение прежних и новых байтов.`}),(0,h.jsx)(r,{code:`before = path.read_bytes()
service.select_tasks(is_done=False)
assert path.read_bytes() == before`,question:`Какую гарантию этот фрагмент не доказывает?`,options:[`Что метод не вызывал storage.save()`,`Что исходный файл содержит те же байты после чтения`,`Что выборка вернула результат метода`],correctIndex:0,explanation:`Файл мог быть записан повторно с тем же содержимым. Для факта вызова нужен наблюдаемый счётчик save_calls или эквивалентная обёртка.`,fix:`observed_storage.save_calls = 0
service.select_tasks(is_done=False)
assert observed_storage.save_calls == 0`}),(0,h.jsx)(a,{tone:`info`,children:`Такой тест сервиса уже есть. В третьей карточке практики отметим его в матрице и не будем писать второй такой же.`})]}),(0,h.jsxs)(l,{number:`05`,title:`CLI и HTTP используют общее ядро приложения`,children:[(0,h.jsx)(c,{children:`CLI показывает результат команды, HTTP формирует ответ, а правила приложения выполняет PlannerService. Даже если сценарий проходит через все слои, каждый тест проверяет свою часть.`}),(0,h.jsx)(`p`,{children:`Приложение создаёт PlannerService и передаёт ему хранилище. CLI обрабатывает команды, HTTP-маршрут читает запрос и формирует ответ. Модели не нужен FastAPI, а сервису не нужны функции HTTP-маршрута. Импорты покажут связи между файлами, но сами по себе не доказывают ошибку.`}),(0,h.jsx)(`p`,{children:`CLI-тесты проверяют команды, сообщения и число сохранений. API-тесты проверяют статусы, JSON и состояние сервиса. В tests/test_contract.py проверяются HTTP-входы и OpenAPI. В третьей карточке мы сопоставим эти готовые тесты с матрицей, не собирая их в один большой сценарий.`}),(0,h.jsx)(`p`,{children:`Если тест использует app.state.planner или создаёт PlannerService, запишем это в матрицу. Если модель импортирует FastAPI или CLI принимает решение за сервис, укажем конкретный пример и проверим его роль. В этой практике проверяем тесты и матрицу; код приложения не меняем.`}),(0,h.jsx)(`p`,{children:`Матрица показывает, какие тесты уже есть. В ней появятся ссылки на два новых файла: tests/test_models.py и tests/test_storage.py. Строки про сервис, JSON, CLI и HTTP будут ссылаться на готовые тесты. Если запись не совпадает с тестом, исправим её и укажем точное имя проверки.`})]}),(0,h.jsxs)(l,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,h.jsx)(c,{children:`Переход A→B такой: в A есть тесты сервиса, JSON, CLI и HTTP, но нет двух unit-тестов. В B появятся тесты Task и MemoryStorage, а матрица будет ссылаться на реальные проверки всех слоёв.`}),(0,h.jsx)(f,{variant:`connected`,items:[{title:`Сверим существующие тесты`,description:`В карточке 3 найдём эти тесты и запишем, что именно каждый проверяет.`},{title:`Проверим Task и MemoryStorage`,description:`В карточке 1 проверим tags у двух Task; в карточке 2 проверим списки и ссылки в MemoryStorage.`},{title:`Обновим карту доказательств`,description:`В карточке 3 укажем новые и готовые тесты и их фактический результат.`}]}),(0,h.jsx)(`p`,{children:`Начните с карточек по порядку: добавьте тест Task, добавьте тест MemoryStorage, затем обновите docs/test-matrix.md. Тесты сервиса, JSON, CLI и HTTP уже есть, поэтому оставьте их и укажите в матрице. В 59.1 свяжем HTTP-операции одной историей, опираясь на готовые проверки.`}),(0,h.jsx)(`p`,{children:`В карточке Task каждое действие проверяется отдельным assertion: оба списка сначала пусты, после добавления метки изменился только первый. В карточке MemoryStorage сначала проверяется копия контейнера при создании, load() и save(), затем общая ссылка на Task. В матрице у каждой строки должны совпасть три вещи: риск, существующий тест и результат, который этот тест действительно проверяет.`})]}),(0,h.jsx)(i,{points:[(0,h.jsx)(h.Fragment,{children:`Граница теста определяет, какой вывод подтверждён результатом.`}),(0,h.jsx)(h.Fragment,{children:`Task хранит собственный изменяемый список tags для каждого экземпляра.`}),(0,h.jsx)(h.Fragment,{children:`MemoryStorage копирует контейнер списка и сохраняет ссылки на те же Task.`}),(0,h.jsx)(h.Fragment,{children:`Тесты сервиса, JSON, CLI и HTTP уже покрывают свои отдельные гарантии.`}),(0,h.jsx)(h.Fragment,{children:`В 59.1 существующие проверки останутся опорой для связанного workflow.`})]})]})}export{g as Lesson59};